package com.fream.back.domain.m85.controller.command;

import com.fream.back.domain.m85.dto.Xqg40RequestDto;
import com.fream.back.domain.m85.dto.Xzt63RequestDto;
import com.fream.back.domain.m85.service.command.Xzt63CommandService;
import com.fream.back.global.utils.SecurityUtils;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/sale-bids")
@RequiredArgsConstructor
public class Xzt63CommandController {

    private final Xzt63CommandService saleBidCommandService;


    @PostMapping
    public ResponseEntity<Long> createSaleBid(
            @RequestBody Xzt63RequestDto requestDto) {
        String email = SecurityUtils.extractEmailFromSecurityContext();
        Long saleBidId = saleBidCommandService.createSaleBid(
                email,
                requestDto.getProductSizeId(),
                requestDto.getBidPrice(),
                requestDto.getReturnAddress(),
                requestDto.getPostalCode(),
                requestDto.getReceiverPhone(),
                requestDto.isWarehouseStorage()
        ).getId();
        return ResponseEntity.ok(saleBidId);
    }


    @DeleteMapping("/{saleBidId}")
    public ResponseEntity<Void> deleteSaleBid(
            @PathVariable("saleBidId") Long saleBidId) {
        saleBidCommandService.deleteSaleBid(saleBidId);
        return ResponseEntity.ok().build();
    }

    @PostMapping("/instant")
    public ResponseEntity<Long> createInstantSale(
            @RequestBody Xqg40RequestDto requestDto) {
        String sellerEmail = SecurityUtils.extractEmailFromSecurityContext();
        Long saleId = saleBidCommandService.createInstantSaleBid(
                requestDto.getOrderBidId(),
                sellerEmail,
                requestDto.getReturnAddress(),
                requestDto.getPostalCode(),
                requestDto.getReceiverPhone()
        );
        return ResponseEntity.ok(saleId);
    }
}










    @PostMapping("/instant")
    public ResponseEntity<ResponseDto<Long>> createInstantOrderBid(@RequestBody @Valid Xcr44RequestDto requestDto) {

        String email = SecurityUtils.extractAndValidateEmailForOrderBid("즉시 구매 입찰 생성");

        log.info("사용자 [{}]가 판매 입찰(ID: {})에 대한 즉시 구매를 요청합니다. 창고 보관 여부: {}",
                email, requestDto.getSaleBidId(), requestDto.isWarehouseStorage());


        Xjt45RequestDto paymentRequest = enrichPaymentRequest(requestDto.getPaymentRequest(), email);


        Long orderId = orderBidCommandService.createInstantOrderBid(
                email,
                requestDto.getSaleBidId(),
                requestDto.getAddressId(),
                requestDto.isWarehouseStorage(),
                paymentRequest
        ).getId();

        return ResponseEntity.ok(ResponseDto.success(orderId, "즉시 구매가 성공적으로 처리되었습니다."));
    }
