 58	    @Transactional
 59	    public Xhq12 createOrderFromBid(Xjm45 user, Xcc44 productSize, int bidPrice) {
 60	        try {
 62	            if (user == null) {
 63	                throw new Xwn18Exception("사용자 정보가 없습니다.");
