111	    @Transactional
112	    public void processPaymentAndShipment(Long orderId, String userEmail, Xsw86RequestDto requestDto) {
113	        if (orderId == null) {
114	            throw new Xwn18Exception("주문 ID가 없습니다.");
115	        }
116	        if (userEmail == null || userEmail.trim().isEmpty()) {
117	            throw new Xjf78Exception("사용자 정보가 없습니다.");
118	        }
119	        if (requestDto == null) {
120	            throw new Xtv55Exception("결제 및 배송 정보가 없습니다.");
121	        }
123	        try {
125	            Xjm45 user = userQueryService.findByEmail(userEmail);
126	            Xhq12 order = orderRepository.findById(orderId)
127	                    .orElseThrow(() -> new Xhr44Exception("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
130	            if (!order.getUser().getId().equals(user.getId())) {
131	                throw new Xjf78Exception("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
132	            }
135	            validatePaymentShipmentRequest(requestDto);
137	            try {
139	                Xjt45 payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
140	                order.assignPayment(payment);
141	            } catch (Exception e) {
142	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
143	                throw new Xwf42Exception("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
144	            }
146	            try {
148	                Xfr60 shipment = orderShipmentCommandService.createOrderShipment(
149	                        order,
150	                        requestDto.getReceiverName(),
151	                        requestDto.getReceiverPhone(),
152	                        requestDto.getPostalCode(),
153	                        requestDto.getAddress()
154	                );
155	                order.assignOrderShipment(shipment);
156	            } catch (Exception e) {
157	                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
158	                throw new Xjb41Exception("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
159	            }
161	            try {
163	                if (requestDto.isWarehouseStorage()) {
165	                    order.updateStatus(Xhq12Status.PAYMENT_COMPLETED);
166	                    order.updateStatus(Xhq12Status.PREPARING);
167	                    order.updateStatus(Xhq12Status.IN_WAREHOUSE);
170	                    Xms75 warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
171	                    order.assignWarehouseStorage(warehouseStorage);
172	                    order.updateStatus(Xhq12Status.COMPLETED);
173	                } else {
175	                    order.updateStatus(Xhq12Status.PAYMENT_COMPLETED);
176	                    order.updateStatus(Xhq12Status.PREPARING);
177	                }
178	            } catch (Xms75Exception e) {
179	                log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
180	                throw new Xkd21Exception("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
181	            } catch (Exception e) {
182	                log.error("주문 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
183	                throw new Xbb45Exception("주문 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
