   383	    private void notifyUsersAndUpdateSaleStatus(Xhq12 order, Xjt45 payment) {
   384	        try {
   385	            log.info("결제 관련 알림 및 판매 상태 업데이트 시작: 주문ID={}", order.getId());
   388	            Xtw92 orderBid = order.getOrderBid();
   389	            if (orderBid == null) {
   391	                Xzt63 saleBid = saleBidQueryService.findByOrderId(order.getId());
   392	                if (saleBid == null) {
   393	                    log.warn("주문에 연결된 판매 입찰 정보가 없습니다: 주문ID={}", order.getId());
   394	                    return;
   395	                }
   397	                Xpj42 sale = saleBid.getSale();
   398	                if (sale == null) {
