   553	            if (!payment.getStatus().canTransitionTo(Xjt45Status.REFUND_REQUESTED)) {
   554	                throw new Xjt45Exception(Xjt45ErrorCode.INVALID_PAYMENT_STATUS,
   555	                        "현재 상태에서 환불 요청을 진행할 수 없습니다. 현재 상태: " + payment.getStatus());
